eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   DAILY_REFLECTIONS_DATABASE: () => (/* binding */ DAILY_REFLECTIONS_DATABASE),\n/* harmony export */   getReflectionByDate: () => (/* binding */ getReflectionByDate)\n/* harmony export */ });\n/* harmony import */ var _lib_utils_vietnamese__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! @/lib/utils/vietnamese */ \"(ssr)/./src/lib/utils/vietnamese.ts\");\n\n// ============================================================================\n// SUY NIỆM LỜI CHÚA HẰNG NGÀY - CHUẨN 8 PHẦN LINH ĐẠO CÔNG GIÁO\n// 1. Lời Chúa - 2. Bối cảnh - 3. Giải thích - 4. Sứ điệp chính - \n// 5. Liên hệ đời sống - 6. Câu hỏi suy gẫm - 7. Quyết tâm thực hành - 8. Lời nguyện\n// ============================================================================\nconst DAILY_REFLECTIONS_DATABASE = [\n    {\n        id: \"refl-today\",\n        date: \"2026-11-04\",\n        title: \"Điều Kiện Để Trở N\\xean M\\xf4n Đệ Đức Kit\\xf4: Từ Bỏ & V\\xe1c Thập Gi\\xe1\",\n        scriptureReference: \"Lc 14,25-33\",\n        scriptureText: \"Ai kh\\xf4ng v\\xe1c thập gi\\xe1 m\\xecnh m\\xe0 đi theo T\\xf4i, th\\xec kh\\xf4ng thể l\\xe0m m\\xf4n đệ T\\xf4i được... Ai trong anh em kh\\xf4ng từ bỏ tất cả của cải m\\xecnh c\\xf3, th\\xec kh\\xf4ng thể l\\xe0m m\\xf4n đệ T\\xf4i được.\",\n        // 1. Bối cảnh\n        background: \"Đức Gi\\xeasu đang tr\\xean chặng đường quyết định tiến về Gi\\xearusalem, nơi Ng\\xe0i sẽ chịu thương kh\\xf3 v\\xe0 chịu chết tr\\xean thập gi\\xe1. Đ\\xe1m đ\\xf4ng h\\xe0o hứng đi theo Ng\\xe0i v\\xec chứng kiến c\\xe1c ph\\xe9p lạ hoặc hy vọng về một vương quốc trần thế giải ph\\xf3ng khỏi \\xe1ch đế quốc R\\xf4ma. Đức Gi\\xeasu quay lại, đối diện với họ v\\xe0 l\\xe0m r\\xf5 những đ\\xf2i hỏi cốt l\\xf5i, kh\\xf4ng ảo tưởng của bậc sống m\\xf4n đệ.\",\n        // 2. Giải thích\n        explanation: 'C\\xe1ch diễn đạt \"dứt bỏ / gh\\xe9t\" (tiếng H\\xedpri mang nghĩa y\\xeau \\xedt hơn hoặc đặt ưu ti\\xean thứ yếu) kh\\xf4ng c\\xf3 \\xfd x\\xfai giục căm gh\\xe9t người th\\xe2n, nhưng đ\\xf2i hỏi t\\xecnh y\\xeau d\\xe0nh cho Đức Kit\\xf4 phải l\\xe0 số một tuyệt đối, vượt tr\\xean mọi tương quan huyết thống hay t\\xecnh cảm tự nhi\\xean. Hai dụ ng\\xf4n x\\xe2y th\\xe1p v\\xe0 vua đi đ\\xe1nh trận nhấn mạnh sự nghi\\xeam t\\xfac, tỉnh t\\xe1o v\\xe0 c\\xe2n nhắc kỹ lưỡng: bước theo Ch\\xfaa kh\\xf4ng phải l\\xe0 một ph\\xfat bốc đồng cảm x\\xfac, m\\xe0 l\\xe0 một sự dấn th\\xe2n trọn vẹn cả cuộc đời.',\n        // 3. Sứ điệp chính\n        coreMessage: \"L\\xe0m m\\xf4n đệ Đức Kit\\xf4 kh\\xf4ng phải l\\xe0 cuộc dạo chơi \\xeam đềm hay phương tiện t\\xecm kiếm danh vọng, nhưng l\\xe0 đ\\xf3n nhận Thập Gi\\xe1 mỗi ng\\xe0y v\\xe0 sẵn s\\xe0ng từ bỏ những b\\xe1m v\\xedu quyến luyến trần gian để để Ch\\xfaa l\\xe0m chủ duy nhất t\\xe2m hồn m\\xecnh.\",\n        // 4. Liên hệ đời sống\n        lifeApplication: 'Trong cuộc sống h\\xf4m nay ngập tr\\xe0n chủ nghĩa ti\\xeau thụ v\\xe0 c\\xe1 nh\\xe2n hưởng thụ, người Kit\\xf4 hữu thường dễ bị c\\xe1m dỗ chọn một thứ \"đạo Kit\\xf4 kh\\xf4ng c\\xf3 thập gi\\xe1\". Ch\\xfang ta muốn ơn cứu độ nhưng ngại hy sinh; muốn y\\xeau thương nhưng sợ thiệt th\\xf2i. Ch\\xfaa mời gọi ch\\xfang ta can đảm đặt Ng\\xe0i l\\xean tr\\xean tiền t\\xe0i, danh vọng v\\xe0 c\\xe1i t\\xf4i \\xedch kỷ.',\n        // 5. Câu hỏi suy gẫm\n        reflectionQuestions: [\n            'Điều g\\xec đang l\\xe0 \"của cải\", \"vướng bận\" hoặc \"tương quan\" cản trở t\\xf4i dấn th\\xe2n theo Ch\\xfaa c\\xe1ch triệt để nhất?',\n            \"Khi gặp gian nan, thử th\\xe1ch hoặc nghịch cảnh trong gia đ\\xecnh v\\xe0 c\\xf4ng việc, t\\xf4i đ\\xf3n nhận như một phần của thập gi\\xe1 Ch\\xfaa hay t\\xf4i chỉ biết o\\xe1n tr\\xe1ch, n\\xe9 tr\\xe1nh?\",\n            \"T\\xf4i c\\xf3 d\\xe1m chọn sống theo gi\\xe1 trị Tin Mừng (trung thực, khi\\xeam nhường, y\\xeau thương kẻ th\\xf9) dẫu bị thế gian ch\\xea cười hoặc thiệt th\\xf2i?\"\n        ],\n        // 6. Quyết tâm thực hành\n        practicalResolution: \"H\\xf4m nay, t\\xf4i quyết t\\xe2m từ bỏ một th\\xf3i quen hưởng thụ hoặc một lời n\\xf3i ph\\xe0n n\\xe0n; thay v\\xe0o đ\\xf3, sẵn l\\xf2ng l\\xe0m một việc phục vụ \\xe2m thầm cho một người trong gia đ\\xecnh hoặc nơi sở l\\xe0m m\\xe0 kh\\xf4ng đ\\xf2i hỏi đền đ\\xe1p.\",\n        // 7. Lời nguyện\n        prayer: \"Lạy Ch\\xfaa Gi\\xeasu, Ch\\xfaa đ\\xe3 y\\xeau thương ch\\xfang con đến nỗi tự hiến mạng sống tr\\xean c\\xe2y Thập Gi\\xe1 để cứu chuộc ch\\xfang con. Xin ban cho con một tr\\xe1i tim quảng đại, biết can đảm v\\xe1c thập gi\\xe1 bổn phận hằng ng\\xe0y m\\xe0 kh\\xf4ng sờn l\\xf2ng nản ch\\xed. Xin gỡ bỏ khỏi t\\xe2m hồn con những d\\xednh b\\xe9n m\\xf9 qu\\xe1ng nơi của cải trần thế, để con thanh thản bước đi sau ch\\xe2n Ch\\xfaa, Đấng l\\xe0 đường, l\\xe0 sự thật v\\xe0 l\\xe0 sự sống đời đời của con. Amen.\",\n        category: \"Ơn gọi & Đời sống đức tin\",\n        author: \"Lm. Phaol\\xf4 Nguyễn Văn Thanh - Chuy\\xean san Phụng Vụ & Lời Ch\\xfaa\"\n    },\n    {\n        id: \"refl-yesterday\",\n        date: \"2026-11-03\",\n        title: \"Bữa Tiệc Nước Trời & Lời Mời Gọi Kh\\xf4ng Điều Kiện\",\n        scriptureReference: \"Lc 14,15-24\",\n        scriptureText: \"Chủ bảo: H\\xe3y ra c\\xe1c đường lộ v\\xe0 bụi bờ r\\xe0o, \\xe9p người ta v\\xe0o cho đầy nh\\xe0 của ta. V\\xec ta bảo cho c\\xe1c ngươi biết: Kh\\xf4ng ai trong những kẻ đ\\xe3 được mời trước kia sẽ được nếm dự tiệc của ta!\",\n        background: \"Đức Gi\\xeasu dự tiệc tại nh\\xe0 một thủ l\\xe3nh Pharis\\xeau v\\xe0o ng\\xe0y Sab\\xe1t. Nh\\xe2n c\\xe2u n\\xf3i của một thực kh\\xe1ch về hạnh ph\\xfac được dự tiệc Nước Thi\\xean Ch\\xfaa, Người đ\\xe3 mạc khải qua dụ ng\\xf4n về th\\xe1i độ từ khước ơn cứu độ của giới l\\xe3nh đạo t\\xf4n gi\\xe1o Do Th\\xe1i v\\xe0 ơn mở rộng Nước Trời cho mu\\xf4n d\\xe2n.\",\n        explanation: \"C\\xe1c l\\xfd do từ chối bữa tiệc (mua đất, tậu b\\xf2, lấy vợ) tự th\\xe2n đều l\\xe0 những sinh hoạt đời thường ch\\xednh đ\\xe1ng, nhưng ch\\xfang trở th\\xe0nh tai hại chết người khi bị đặt cao hơn Lời Mời Gọi của Thi\\xean Ch\\xfaa. Những người ngh\\xe8o khổ, t\\xe0n tật, đui m\\xf9 l\\xe0 h\\xecnh ảnh của những kẻ bị x\\xe3 hội ruồng bỏ nhưng lại khi\\xeam nhường đ\\xf3n nhận \\xe2n sủng cứu rỗi.\",\n        coreMessage: \"Nước Trời l\\xe0 bữa tiệc của \\xe2n sủng nhưng đ\\xf2i hỏi sự đ\\xf3n nhận với l\\xf2ng biết ơn v\\xe0 ưu ti\\xean tuyệt đối. Đừng để những bận rộn sự đời l\\xe0m ta bỏ lỡ lời mời của Ch\\xfaa.\",\n        lifeApplication: 'Bao lần ch\\xfang ta viện cớ \"bận rộn việc gia đ\\xecnh\", \"\\xe1p lực c\\xf4ng việc\", \"thiếu thời gian\" để lơ l\\xe0 việc tham dự Th\\xe1nh Lễ Ch\\xfaa Nhật, bỏ b\\xea giờ kinh tối gia đ\\xecnh hoặc từ chối gi\\xfap đỡ người hoạn nạn? Bận rộn trần thế c\\xf3 thể trở th\\xe0nh c\\xe1i bẫy ru ngủ linh hồn xa rời Ch\\xfaa.',\n        reflectionQuestions: [\n            \"T\\xf4i đang coi trọng điều g\\xec hơn cuộc hẹn h\\xf2 thi\\xeang li\\xeang với Ch\\xfaa qua Th\\xe1nh Lễ v\\xe0 Lời Người?\",\n            \"T\\xf4i c\\xf3 th\\xe1i độ kh\\xe9p k\\xedn hay mở l\\xf2ng đ\\xf3n nhận những người ngh\\xe8o khổ, yếu thế xung quanh m\\xecnh?\"\n        ],\n        practicalResolution: \"D\\xe0nh ra đ\\xfang 15 ph\\xfat thinh lặng buổi tối h\\xf4m nay, tắt điện thoại để tạ ơn Ch\\xfaa v\\xe0 lắng nghe Lời Ng\\xe0i chỉ dẫn cho cuộc sống.\",\n        prayer: \"Lạy Ch\\xfaa, Bữa Tiệc Th\\xe1nh Thể l\\xe0 hương thơm nếm trước hạnh ph\\xfac Nước Trời. Xin chữa l\\xe0nh sự chai đ\\xe1 v\\xe0 lạnh nhạt trong t\\xe2m hồn con, để con kh\\xf4ng bao giờ từ khước lời mời tha thiết của Ng\\xe0i. Amen.\",\n        category: \"B\\xe1c \\xe1i & Tỉnh thức\",\n        author: \"Đan viện Biển Đức Thi\\xean Phước\"\n    }\n];\nfunction getReflectionByDate(dateStr) {\n    const found = DAILY_REFLECTIONS_DATABASE.find((r)=>r.date === dateStr);\n    return (0,_lib_utils_vietnamese__WEBPACK_IMPORTED_MODULE_0__.normalizeObject)(found || DAILY_REFLECTIONS_DATABASE[0]);\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/daily-reflections.ts\n");

