eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   LITURGICAL_READINGS_ARCHIVE: () => (/* binding */ LITURGICAL_READINGS_ARCHIVE),\n/* harmony export */   getLiturgicalReadingByDate: () => (/* binding */ getLiturgicalReadingByDate)\n/* harmony export */ });\n/* harmony import */ var _lib_utils_vietnamese__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! @/lib/utils/vietnamese */ \"(ssr)/./src/lib/utils/vietnamese.ts\");\n\n// ============================================================================\n// HỆ THỐNG BÀI ĐỌC PHỤNG VỤ THÁNH CÔNG GIÁO CHUẨN MỰC\n// Bản dịch phụng vụ chính thức - Nguồn Ủy Ban Phụng Tự / HĐGMVN\n// ============================================================================\nconst LITURGICAL_READINGS_ARCHIVE = [\n    {\n        id: \"reading-today\",\n        date: \"2026-11-04\",\n        title: \"Thứ Tư Tuần XXXI M\\xf9a Thường Ni\\xean - Th\\xe1nh Car\\xf4l\\xf4 B\\xf4r\\xf4m\\xea\\xf4, Gi\\xe1m mục (Lễ Nhớ)\",\n        season: \"ORDINARY_TIME\",\n        seasonName: \"M\\xf9a Thường Ni\\xean\",\n        color: \"WHITE\",\n        colorName: \"M\\xe0u Trắng\",\n        rank: \"MEMORIAL\",\n        rankName: \"Lễ Nhớ Bắt Buộc\",\n        cycle: \"Năm B - Năm II\",\n        liturgicalWeek: \"Tuần XXXI Thường Ni\\xean\",\n        saintOfTheDay: \"Th\\xe1nh Car\\xf4l\\xf4 B\\xf4r\\xf4m\\xea\\xf4, Gi\\xe1m mục (1538 - 1584), nh\\xe0 cải c\\xe1ch vĩ đại thời C\\xf4ng đồng Trent\\xf4.\",\n        firstReading: {\n            reference: \"Pl 2,12-18\",\n            passage: \"Thư của Th\\xe1nh Phaol\\xf4 T\\xf4ng đồ gửi t\\xedn hữu Phil\\xedpph\\xea\",\n            theme: \"H\\xe3y gắng sức đạt cho được ơn cứu độ; Thi\\xean Ch\\xfaa ch\\xednh l\\xe0 Đấng t\\xe1c động nơi anh em.\",\n            text: `Anh em thân mến, như anh em đã luôn luôn vâng phục, không phải chỉ khi tôi có mặt, nhưng hơn thế nữa bây giờ khi tôi vắng mặt, anh em hãy biết run sợ mà gắng sức đạt cho được ơn cứu độ của mình. Vì chính Thiên Chúa là Đấng tác động nơi anh em cả ý muốn lẫn hành động theo sở thích tốt lành của Người.\n\nHãy làm mọi việc mà đừng kêu ca than vãn hay trù trừ phân vân, ngõ hầu anh em trở nên thanh liêm vẹn toàn, con cái bất khả khiển trách của Thiên Chúa giữa một thế hệ gian tà và sa đọa; giữa họ, anh em hãy chiếu sáng như những vì sao trên bầu trời thế giới, bằng cách nắm giữ vững vàng Lời ban sự sống, để tôi có thể tự hào trong ngày Đức Kitô, rằng tôi đã không chạy uổng công, cũng không lao nhọc vô ích.\n\nNhưng cho dẫu tôi phải đổ máu mình ra như của lễ tưới lên hy lễ và tế phẩm đức tin của anh em, tôi cũng vui mừng và cùng chia sẻ niềm vui ấy với toàn thể anh em. Anh em cũng vậy, hãy hân hoan và cùng chung vui với tôi.`\n        },\n        responsorialPsalm: {\n            reference: \"Tv 26 (27),1.4.13-14 (Đ. c.1a)\",\n            refrain: \"Ch\\xfaa l\\xe0 nguồn \\xe1nh s\\xe1ng v\\xe0 ơn cứu độ của t\\xf4i.\",\n            verses: [\n                \"Ch\\xfaa l\\xe0 nguồn \\xe1nh s\\xe1ng v\\xe0 ơn cứu độ của t\\xf4i, t\\xf4i c\\xf2n phải sợ ai? Ch\\xfaa l\\xe0 th\\xe0nh lũy bảo vệ mạng sống t\\xf4i, t\\xf4i n\\xe0o phải khiếp h\\xe3i?\",\n                \"C\\xf3 một điều t\\xf4i n\\xe0i xin Đức Ch\\xfaa, một điều t\\xf4i t\\xecm kiếm m\\xe3i th\\xf4i: l\\xe0 được ngụ trong nh\\xe0 Đức Ch\\xfaa suốt mọi ng\\xe0y đời t\\xf4i, để ngắm nh\\xecn vẻ duy\\xean d\\xe1ng của Người v\\xe0 chi\\xeam ngưỡng th\\xe1nh điện.\",\n                \"T\\xf4i vững tin sẽ được nh\\xecn ngắm l\\xf2ng nh\\xe2n hậu của Đức Ch\\xfaa trong c\\xf5i đất d\\xe0nh cho kẻ sống! H\\xe3y cậy tr\\xf4ng v\\xe0o Đức Ch\\xfaa, h\\xe3y mạnh bạo l\\xean, can đảm l\\xean, v\\xe0 cậy tr\\xf4ng v\\xe0o Đức Ch\\xfaa!\"\n            ]\n        },\n        gospelAcclamation: {\n            verse: \"1 Pr 4,14\",\n            text: \"Al-l\\xea-lui-a. Al-l\\xea-lui-a. Nếu anh em bị sỉ nhục v\\xec danh Đức Kit\\xf4, anh em thật c\\xf3 ph\\xfac, v\\xec Thần Kh\\xed vinh hiển của Thi\\xean Ch\\xfaa đang ngự tr\\xean anh em. Al-l\\xea-lui-a.\"\n        },\n        gospel: {\n            reference: \"Lc 14,25-33\",\n            passage: \"Tin Mừng Đức Gi\\xeasu Kit\\xf4 theo Th\\xe1nh Lu-ca\",\n            theme: \"Ai kh\\xf4ng từ bỏ hết thảy của cải m\\xecnh c\\xf3, th\\xec kh\\xf4ng thể l\\xe0m m\\xf4n đệ Thầy được.\",\n            text: `Khi ấy, có rất đông người cùng đi đường với Đức Giêsu. Người quay lại bảo họ:\n\n\"Ai đến với Tôi mà không dứt bỏ lòng yêu mến cha mẹ, vợ con, anh chị em, và cả mạng sống mình nữa, thì không thể làm môn đệ Tôi được. Ai không vác thập giá mình mà đi theo Tôi, thì không thể làm môn đệ Tôi được.\n\nQuả thế, ai trong anh em muốn xây một cây tháp mà trước tiên lại không ngồi xuống tính toán phí tổn, xem mình có đủ tiền hoàn tất không? Kẻo khi đặt móng rồi mà không thể làm xong, thì mọi người thấy đều chế giễu: 'Người này đã khởi công xây dựng mà không có sức hoàn tất!'.\n\nHoặc có vua nào đi giao chiến với một vua khác mà trước tiên lại không ngồi bàn tính xem mình có thể đem mười ngàn quân nghênh chiến với đối phương mang hai mươi ngàn quân đánh mình không? Bằng không, khi người kia còn ở đàng xa, vua ấy đã sai sứ giả đến cầu hòa.\n\nCũng thế, ai trong anh em không từ bỏ tất cả của cải mình có, thì không thể làm môn đệ Tôi được.\"`\n        },\n        openingPrayer: \"Lạy Ch\\xfaa, xin giữ g\\xecn l\\xf2ng d\\xe2n Ch\\xfaa nơi tinh thần sốt mến m\\xe0 Th\\xe1nh Gi\\xe1m mục Car\\xf4l\\xf4 B\\xf4r\\xf4m\\xea\\xf4 đ\\xe3 n\\xeau gương, để Hội Th\\xe1nh kh\\xf4ng ngừng đổi mới theo khu\\xf4n mẫu Đức Kit\\xf4 v\\xe0 chiếu tỏa \\xe1nh s\\xe1ng ơn cứu độ cho to\\xe0n thế giới.\",\n        prayerOfFaithful: [\n            \"Cầu cho Hội Th\\xe1nh: Xin cho c\\xe1c mục tử trong Hội Th\\xe1nh lu\\xf4n noi gương Th\\xe1nh Car\\xf4l\\xf4, d\\xe2ng hiến trọn cuộc đời v\\xec phần rỗi tha nh\\xe2n.\",\n            \"Cầu cho c\\xe1c nh\\xe0 l\\xe3nh đạo: Xin cho c\\xe1c nh\\xe0 l\\xe3nh đạo quốc gia biết d\\xf9ng quyền b\\xednh phục vụ c\\xf4ng l\\xfd v\\xe0 bảo vệ những người ngh\\xe8o khổ.\",\n            \"Cầu cho c\\xe1c t\\xedn hữu: Xin cho mỗi người ch\\xfang con biết can đảm v\\xe1c thập gi\\xe1 mỗi ng\\xe0y v\\xe0 từ bỏ những b\\xe1m v\\xedu trần gian để bước theo Ch\\xfaa Gi\\xeasu.\"\n        ],\n        closingPrayer: \"Lạy Ch\\xfaa, ch\\xfang con vừa l\\xe3nh nhận M\\xecnh v\\xe0 M\\xe1u Th\\xe1nh Đức Kit\\xf4; xin \\xe2n sủng th\\xe1nh n\\xe0y củng cố l\\xf2ng ch\\xfang con ki\\xean vững trong đức mến v\\xe0 can trường l\\xe0m chứng cho sự thật.\",\n        sourceNote: \"Tr\\xedch S\\xe1ch B\\xe0i Đọc Phụng Vụ Th\\xe1nh Lễ - Ủy Ban Phụng Tự trực thuộc Hội Đồng Gi\\xe1m Mục Việt Nam.\"\n    },\n    {\n        id: \"reading-yesterday\",\n        date: \"2026-11-03\",\n        title: \"Thứ Ba Tuần XXXI M\\xf9a Thường Ni\\xean - Th\\xe1nh M\\xe1ctin\\xf4 Porres (Lễ Nhớ)\",\n        season: \"ORDINARY_TIME\",\n        seasonName: \"M\\xf9a Thường Ni\\xean\",\n        color: \"WHITE\",\n        colorName: \"M\\xe0u Trắng\",\n        rank: \"OPTIONAL_MEMORIAL\",\n        rankName: \"Lễ Nhớ T\\xf9y Chọn\",\n        cycle: \"Năm B - Năm II\",\n        liturgicalWeek: \"Tuần XXXI Thường Ni\\xean\",\n        saintOfTheDay: \"Th\\xe1nh M\\xe1ctin\\xf4 Porres, Tu sĩ D\\xf2ng Đa Minh (1579 - 1639), gương s\\xe1ng về l\\xf2ng b\\xe1c \\xe1i khi\\xeam nhường đối với người ngh\\xe8o v\\xe0 người bệnh tật.\",\n        firstReading: {\n            reference: \"Pl 2,5-11\",\n            passage: \"Thư của Th\\xe1nh Phaol\\xf4 T\\xf4ng đồ gửi t\\xedn hữu Phil\\xedpph\\xea\",\n            theme: \"Đức Kit\\xf4 đ\\xe3 tự hạ m\\xecnh, v\\xec thế Thi\\xean Ch\\xfaa đ\\xe3 si\\xeau t\\xf4n Người.\",\n            text: `Anh em hãy có cùng một tâm tình như chính Đức Kitô Giêsu đã có:\nĐức Giêsu Kitô vốn dĩ là Thiên Chúa mà không nghĩ phải nhất quyết duy trì địa vị ngang hàng với Thiên Chúa, nhưng đã hoàn toàn trút bỏ vinh quang, mặc lấy thân nô lệ, trở nên giống phàm nhân, sống như một người trần thế.\n\nNgười lại còn hạ mình, vâng lời cho đến nỗi bằng lòng chịu chết, chết trên cây thập tự! Chính vì thế, Thiên Chúa đã siêu tôn Người và tặng ban danh hiệu trổi vượt trên muôn ngàn danh hiệu, để khi vừa nghe danh thánh Giêsu, cả trên trời, dưới đất và trong nơi âm phủ, muôn vật phải bái quỳ, và mọi miệng lưỡi phải tuyên xưng rằng: \"Đức Giêsu Kitô là Chúa\", để tôn vinh Thiên Chúa Cha.`\n        },\n        responsorialPsalm: {\n            reference: \"Tv 21 (22),26b-27.28-30a.31-32 (Đ. c.26a)\",\n            refrain: \"Lạy Ch\\xfaa, giữa l\\xf2ng đại hội, con xin ngợi khen Ng\\xe0i.\",\n            verses: [\n                \"Lời khấn nguyền, con xin giữ trọn trước mặt những người k\\xednh sợ Ch\\xfaa. Kẻ ngh\\xe8o h\\xe8n sẽ được ăn no n\\xea; những ai t\\xecm Ch\\xfaa sẽ ca tụng Người.\",\n                \"Mọi c\\xf9ng c\\xf5i trần gian sẽ nhớ lại v\\xe0 quay về với Ch\\xfaa; mu\\xf4n gia tộc c\\xe1c d\\xe2n tộc sẽ phủ phục trước nhan Ng\\xe0i.\",\n                \"D\\xf2ng d\\xf5i tương lai sẽ phụng sự Người; người ta sẽ truyền tụng về Ch\\xfaa cho thế hệ mai sau, loan b\\xe1o đức c\\xf4ng ch\\xednh của Người cho d\\xe2n chưa sinh ra.\"\n            ]\n        },\n        gospelAcclamation: {\n            verse: \"Mt 11,28\",\n            text: \"Al-l\\xea-lui-a. Al-l\\xea-lui-a. Tất cả những ai đang vất vả mang g\\xe1nh nặng nề, h\\xe3y đến c\\xf9ng T\\xf4i, T\\xf4i sẽ cho nghỉ ngơi bồi dưỡng. Al-l\\xea-lui-a.\"\n        },\n        gospel: {\n            reference: \"Lc 14,15-24\",\n            passage: \"Tin Mừng Đức Gi\\xeasu Kit\\xf4 theo Th\\xe1nh Lu-ca\",\n            theme: \"H\\xe3y đi ra c\\xe1c nẻo đường, bắt người ta v\\xe0o cho đầy nh\\xe0 của Ta.\",\n            text: `Khi ấy, một trong những thực khách nghe Đức Giêsu nói liền thưa với Người: \"Phúc thay ai được dự tiệc trong Nước Thiên Chúa!\".\n\nNgười đáp: \"Một người kia dọn tiệc lớn và mời nhiều người. Đến giờ tiệc, ông sai đầy tớ đi nói với những kẻ đã được mời: 'Xin mời quý vị đến, mọi sự đã sẵn sàng rồi'. Nhưng tất cả đồng thanh cáo lỗi. Người thứ nhất nói: 'Tôi mới mua một thửa đất, cần phải đi xem; xin cho tôi cáo lỗi'. Người khác nói: 'Tôi mới tậu năm cặp bò, tôi đang đi thử chúng; xin cho tôi cáo lỗi'. Người khác nữa lại nói: 'Tôi mới lấy vợ, nên tôi không thể đến được'.\n\nNgười đầy tớ trở về kể lại cho chủ những điều ấy. Chủ nhà nổi giận bảo người đầy tớ: 'Mau ra các đường phố và ngõ hẻm trong thành, đưa những người nghèo khó, tàn tật, đui mù và què quặt vào đây'.\n\nNgười đầy tớ thưa: 'Thưa ông, lệnh ông đã được thi hành mà vẫn còn chỗ'. Chủ bảo: 'Hãy ra các đường lộ và bụi bờ rào, ép người ta vào cho đầy nhà của ta. Vì ta bảo cho các ngươi biết: Không ai trong những kẻ đã được mời trước kia sẽ được nếm dự tiệc của ta!'.\"`\n        },\n        sourceNote: \"Tr\\xedch S\\xe1ch B\\xe0i Đọc Phụng Vụ Th\\xe1nh Lễ - HĐGMVN.\"\n    },\n    {\n        id: \"reading-tomorrow\",\n        date: \"2026-11-05\",\n        title: \"Thứ Năm Tuần XXXI M\\xf9a Thường Ni\\xean\",\n        season: \"ORDINARY_TIME\",\n        seasonName: \"M\\xf9a Thường Ni\\xean\",\n        color: \"GREEN\",\n        colorName: \"M\\xe0u Xanh\",\n        rank: \"WEEKDAY\",\n        rankName: \"Ng\\xe0y Trong Tuần\",\n        cycle: \"Năm B - Năm II\",\n        liturgicalWeek: \"Tuần XXXI Thường Ni\\xean\",\n        firstReading: {\n            reference: \"Pl 3,3-8a\",\n            passage: \"Thư của Th\\xe1nh Phaol\\xf4 T\\xf4ng đồ gửi t\\xedn hữu Phil\\xedpph\\xea\",\n            theme: \"T\\xf4i coi mọi sự l\\xe0 thiệt th\\xf2i so với mối lợi tuyệt vời l\\xe0 được biết Đức Kit\\xf4 Gi\\xeasu.\",\n            text: `Thưa anh em, chính chúng ta mới là những người thực sự chịu phép cắt bì, những người phụng thờ Thiên Chúa nhờ Thần Khí của Người, những người tự hào trong Đức Kitô Giêsu chứ không cậy dựa vào xác phàm. Dầu rằng về phần tôi, tôi có lý do để cậy dựa vào xác phàm. Nếu ai khác tưởng mình có thể cậy dựa vào xác thịt, thì tôi lại càng có lý do hơn: chịu phép cắt bì ngày thứ tám, thuộc dòng giống Israel, chi tộc Bêngiamin, là người Hípri con của người Hípri; về Lề Luật, tôi là người Pharisêu; về lòng nhiệt thành, tôi đã bắt bớ Hội Thánh; còn về sự công chính theo Lề Luật, tôi là người bất khả khiển trách.\n\nNhưng những gì xưa kia là mối lợi cho tôi, thì vì Đức Kitô, tôi đã coi là thiệt thòi. Hơn nữa, tôi coi tất cả mọi sự là thiệt thòi, so với mối lợi tuyệt vời là được biết Đức Kitô Giêsu, Chúa của tôi!`\n        },\n        responsorialPsalm: {\n            reference: \"Tv 104 (105),2-3.4-5.6-7 (Đ. c.3b)\",\n            refrain: \"H\\xe3y vui l\\xean, hỡi những t\\xe2m hồn t\\xecm kiếm Ch\\xfaa!\",\n            verses: [\n                \"H\\xe3y h\\xe1t xướng ch\\xfac tụng Người, đ\\xe0n ca t\\xf4n vinh Ch\\xfaa! H\\xe3y loan b\\xe1o mọi kỳ c\\xf4ng của Người! H\\xe3y tự h\\xe0o v\\xec Th\\xe1nh Danh Người!\",\n                \"H\\xe3y t\\xecm kiếm Ch\\xfaa v\\xe0 sức mạnh của Người, lu\\xf4n lu\\xf4n t\\xecm kiếm t\\xf4n nhan Người! H\\xe3y nhớ lại những kỳ c\\xf4ng Người đ\\xe3 thực hiện, những dấu lạ v\\xe0 ph\\xe1n quyết của miệng Người!\",\n                \"Hỡi d\\xf2ng d\\xf5i Abraham, t\\xf4i tớ Người, hỡi con c\\xe1i Giac\\xf3p, những kẻ Người tuyển chọn! Ch\\xednh Người l\\xe0 Đức Ch\\xfaa, Thi\\xean Ch\\xfaa ch\\xfang ta; c\\xe1c ph\\xe1n quyết của Người bao tr\\xf9m to\\xe0n c\\xf5i đất.\"\n            ]\n        },\n        gospelAcclamation: {\n            verse: \"Mt 11,28\",\n            text: \"Al-l\\xea-lui-a. Al-l\\xea-lui-a. Tất cả những ai đang vất vả mang g\\xe1nh nặng nề, h\\xe3y đến c\\xf9ng T\\xf4i, T\\xf4i sẽ cho nghỉ ngơi bồi dưỡng. Al-l\\xea-lui-a.\"\n        },\n        gospel: {\n            reference: \"Lc 15,1-10\",\n            passage: \"Tin Mừng Đức Gi\\xeasu Kit\\xf4 theo Th\\xe1nh Lu-ca\",\n            theme: \"Tr\\xean trời sẽ vui mừng v\\xec một người tội lỗi ăn năn s\\xe1m hối hơn l\\xe0 v\\xec ch\\xedn mươi ch\\xedn người c\\xf4ng ch\\xednh.\",\n            text: `Khi ấy, các người thu thuế và các tội nhân đều lui tới với Đức Giêsu để nghe Người giảng. Thấy vậy, những người Pharisêu và các kinh sư liền xầm xì phàn nàn: \"Ông này đón tiếp quân tội lỗi và ăn uống với chúng!\".\n\nĐức Giêsu bèn kể cho họ dụ ngôn này: \"Người nào trong các ông có một trăm con chiên mà bị mất một con, lại không để chín mươi chín con kia ngoài đồng vắng mà đi tìm con chiên lạc cho kỳ được? Khi tìm được rồi, người ấy mừng rỡ vác lên vai. Về đến nhà, ông mời bạn bè và hàng xóm lại và bảo: 'Xin chia vui với tôi, vì tôi đã tìm thấy con chiên bị lạc của tôi!'.\n\nTôi bảo cho các ông hay: Cũng thế, trên trời sẽ vui mừng vì một người tội lỗi ăn năn sám hối, hơn là vì chín mươi chín người công chính không cần phải sám hối.\n\nHoặc người phụ nữ nào có mười đồng quan mà đánh mất một đồng, lại không thắp đèn, quét nhà và tìm kiếm cẩn thận cho kỳ được? Khi tìm được rồi, bà mời bạn bè và hàng xóm lại và bảo: 'Xin chia vui với tôi, vì tôi đã tìm thấy đồng quan tôi đã đánh mất!'.\n\nCũng vậy, Tôi nói cho các ông biết: Giữa các thiên sứ của Thiên Chúa sẽ có niềm vui vì một người tội lỗi ăn năn sám hối.\"`\n        },\n        sourceNote: \"Tr\\xedch S\\xe1ch B\\xe0i Đọc Phụng Vụ Th\\xe1nh Lễ - HĐGMVN.\"\n    }\n];\nfunction getLiturgicalReadingByDate(dateStr) {\n    const found = LITURGICAL_READINGS_ARCHIVE.find((r)=>r.date === dateStr);\n    if (found) return (0,_lib_utils_vietnamese__WEBPACK_IMPORTED_MODULE_0__.normalizeObject)(found);\n    // Fallback to today's verified reading\n    return (0,_lib_utils_vietnamese__WEBPACK_IMPORTED_MODULE_0__.normalizeObject)(LITURGICAL_READINGS_ARCHIVE[0]);\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/liturgical-readings.ts\n");

